import { defineConfig } from 'vite';
import path from 'node:path';

const here = (p) => path.resolve(import.meta.dirname, p).replace(/\\/g, '/');
// the admin portal's API and uploaded photos come from the Node server (npm run server)
const api = 'http://localhost:8787';

export default defineConfig({
  server: {
    port: 5188,
    watch: {
      // media and raw data are regenerated by the tools scripts; don't reload the page for every file
      // written. (Absolute paths on purpose: a bare "**/data/**" would also swallow src/data/.)
      ignored: [`${here('public/media')}/**`, `${here('data')}/**`, `${here('tools')}/**`, `${here('storage')}/**`, `${here('server')}/**`],
    },
    proxy: { '/api': api, '/uploads': api },
  },
  plugins: [{
    // /admin → the admin portal page, as the server does in production
    name: 'admin-route',
    configureServer(server) {
      server.middlewares.use((req, res, next) => {
        if (req.url === '/admin' || req.url === '/admin/') req.url = '/admin.html';
        next();
      });
    },
  }],
  build: {
    chunkSizeWarningLimit: 900,
    rollupOptions: { input: { main: here('index.html'), admin: here('admin.html') } },
  },
});
